## Teaching datasets, all generated by wgh_simulate() with the wgh_like preset.
devtools::load_all(quiet = TRUE)

## Book 1 cohort
sim1 <- wgh_simulate(4000, preset = "wgh_like", seed = 2024)
growdat <- as.data.frame(sim1$visits)
usethis::use_data(growdat, overwrite = TRUE, compress = "xz")

## Book 1 Chapter 2: the same cohort as a raw export with injected errors
growdat_raw <- wgh_add_messiness(growdat, rate = 0.03, seed = 2024)
usethis::use_data(growdat_raw, overwrite = TRUE, compress = "xz")

## Book 2 cohort: a 3,000-child subset of the full growdat2 (see wgh_download())
sim2 <- wgh_simulate(30000, preset = "wgh_like", seed = 2026, style = "book2")
set.seed(2026)
ids <- sample(unique(sim2$visits$pid), 3000)
growdat2_mini <- as.data.frame(sim2$visits[sim2$visits$pid %in% ids, ])
growdat2_mini_truth <- as.data.frame(sim2$truth_child[sim2$truth_child$pid %in% ids, ])
usethis::use_data(growdat2_mini, growdat2_mini_truth, overwrite = TRUE, compress = "xz")

## Clinical cases
clinical_cases <- as.data.frame(wgh_simulate_clinical_cases(60, seed = 2024))
usethis::use_data(clinical_cases, overwrite = TRUE, compress = "xz")
